/* Railway Challenge 2024 - NUCLEO-F446RE Configuration File
 *  By Kiran Chinnam (kiran.chinnam@networkrail.co.uk)
 *  Date: 2024-April-09
 *  Version: 2024-04-F2
 * 
 *  Notes: It was discovered that by default, the STM32duino core tries
 *  to use a High Speed Internal Clock at 16 MHz, multiplied via PLL to
 *  get a HCLK of 180MHz and ABP1 Clock of 45MHz. 
 * 
 *  The HSI CLOCK is not stable enough for CAN, so this file overrides
 *  the clock config to use the HSE source which is 8 MHz, generated by
 *  the ST-Link. The other modification is to down-clock slightly to
 *  168 MHz HCLK, with the same APB1 divider of 4 - ABP1 is now clocked
 *  at 42 MHz, which seems to be more stable for CAN.
 * 
 *  When the Nucleo is powered from E5V, the ST-Link clock is not ready
 *  immediately, so the clock config code below checks for HSE clock
 *  init failure and does a core reset so that the STM32F446RE can self
 *  start, when powered by E5V.
 *
 *  The latest version adds a hard fault handler which blinks the
 *  onboard LED rapidly if a hard fault occurs.
 */

#ifndef STM32F446_CONF_H
#define STM32F446_CONF_H

#include <Arduino.h>

void SystemClock_Config(void)
{
  RCC_OscInitTypeDef RCC_OscInitStruct;
  RCC_ClkInitTypeDef RCC_ClkInitStruct;
  RCC_PeriphCLKInitTypeDef PeriphClkInitStruct;

  /**Configure the main internal regulator output voltage
   */
  __HAL_RCC_PWR_CLK_ENABLE();

  __HAL_PWR_VOLTAGESCALING_CONFIG(PWR_REGULATOR_VOLTAGE_SCALE1);

  /**Initializes the CPU, AHB and APB busses clocks
   */
  RCC_OscInitStruct.OscillatorType = RCC_OSCILLATORTYPE_HSE;
  RCC_OscInitStruct.HSEState = RCC_HSE_BYPASS;
  RCC_OscInitStruct.PLL.PLLState = RCC_PLL_ON;
  RCC_OscInitStruct.PLL.PLLSource = RCC_PLLSOURCE_HSE;
  RCC_OscInitStruct.PLL.PLLM = 8;
  RCC_OscInitStruct.PLL.PLLN = 336;
  RCC_OscInitStruct.PLL.PLLP = RCC_PLLP_DIV2;
  RCC_OscInitStruct.PLL.PLLQ = 2;
  RCC_OscInitStruct.PLL.PLLR = 2;
  if (HAL_RCC_OscConfig(&RCC_OscInitStruct) != HAL_OK)
  {
    /* Initialization Error */
    delay(50);
    HAL_NVIC_SystemReset();
  }

  /**Activate the Over-Drive mode
   */
  if (HAL_PWREx_EnableOverDrive() != HAL_OK)
  {
    /* Initialization Error */
    delay(50);
    HAL_NVIC_SystemReset();
  }

  /**Initializes the CPU, AHB and APB busses clocks
   */
  RCC_ClkInitStruct.ClockType = RCC_CLOCKTYPE_HCLK | RCC_CLOCKTYPE_SYSCLK | RCC_CLOCKTYPE_PCLK1 | RCC_CLOCKTYPE_PCLK2;
  RCC_ClkInitStruct.SYSCLKSource = RCC_SYSCLKSOURCE_PLLCLK;
  RCC_ClkInitStruct.AHBCLKDivider = RCC_SYSCLK_DIV1;
  RCC_ClkInitStruct.APB1CLKDivider = RCC_HCLK_DIV4;
  RCC_ClkInitStruct.APB2CLKDivider = RCC_HCLK_DIV2;

  if (HAL_RCC_ClockConfig(&RCC_ClkInitStruct, FLASH_LATENCY_5) != HAL_OK)
  {
    /* Initialization Error */
    delay(50);
    HAL_NVIC_SystemReset();
  }

  PeriphClkInitStruct.PeriphClockSelection = RCC_PERIPHCLK_I2S_APB1 | RCC_PERIPHCLK_RTC;
  PeriphClkInitStruct.PLLI2S.PLLI2SN = 192;
  PeriphClkInitStruct.PLLI2S.PLLI2SP = RCC_PLLI2SP_DIV2;
  PeriphClkInitStruct.PLLI2S.PLLI2SM = 16;
  PeriphClkInitStruct.PLLI2S.PLLI2SR = 2;
  PeriphClkInitStruct.PLLI2S.PLLI2SQ = 2;
  PeriphClkInitStruct.PLLI2SDivQ = 1;
  PeriphClkInitStruct.RTCClockSelection = RCC_RTCCLKSOURCE_LSI;
  PeriphClkInitStruct.I2sApb1ClockSelection = RCC_I2SAPB1CLKSOURCE_PLLI2S;
  if (HAL_RCCEx_PeriphCLKConfig(&PeriphClkInitStruct) != HAL_OK)
  {
    /* Initialization Error */
    delay(50);
    HAL_NVIC_SystemReset();
  }
}

extern "C" void HardFault_Handler(void)
{
#ifdef LED_BUILTIN
  GPIO_TypeDef *gpio = (GPIO_TypeDef *)GPIOA_BASE;
  __disable_irq();
  __HAL_RCC_GPIOA_CLK_ENABLE();
  LL_GPIO_SetPinMode(gpio, LL_GPIO_PIN_5, LL_GPIO_MODE_OUTPUT);
  LL_GPIO_ResetOutputPin(gpio, LL_GPIO_PIN_5);
  for (;;) {
    int i;
    for (i = 0; i < 12; i++) {
      LL_GPIO_TogglePin(gpio, LL_GPIO_PIN_5);
      delayMicroseconds(80000);
    }
    delayMicroseconds(300000);
  }
#else
  while (1);
#endif // LED_BUILTIN
}


#endif